import fs from 'fs';

import { resolveGlobalConfigDir, resolveGlobalConfigPath, resolveLocalEnvPath } from './paths.js';

const API_KEY_NAME = 'OPENAI_API_KEY';

// `[indent][export ]OPENAI_API_KEY[ ]=[ ]` followed by the raw value.
const ENV_DEFINITION = new RegExp(`^(\\s*(?:export\\s+)?${API_KEY_NAME}\\s*=\\s*)(.*)$`);
// A `#` starts a comment in an unquoted value only at the start or after whitespace.
const UNQUOTED_COMMENT = /(^|\s)#/;
// Values that can be written without quotes; anything else is quoted.
const UNQUOTED_SAFE = /^[A-Za-z0-9_.\/:+@,=-]+$/;

const ensureDir = (dirPath) => {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true, mode: 0o700 });
  }
};

const sanitizeValue = (value) => {
  if (typeof value !== 'string') return null;
  return value.trim().replace(/^['"]|['"]$/g, '') || null;
};

const normalizeKey = (key) => {
  const value = typeof key === 'string' ? key.trim() : '';
  if (!value) throw new Error('API key is required');
  if (/[\r\n]/.test(value)) throw new Error('API key must be a single line');
  return value;
};

// Reads a double or single quoted value. Returns null when the closing quote is missing.
const readQuotedValue = (text) => {
  const quote = text[0];
  let value = '';
  for (let index = 1; index < text.length; index += 1) {
    const char = text[index];
    const next = text[index + 1];
    if (quote === '"' && char === '\\' && (next === '"' || next === '\\')) {
      value += next;
      index += 1;
    } else if (char === quote) {
      return { value, trailing: text.slice(index + 1) };
    } else {
      value += char;
    }
  }
  return null;
};

const parseEnvValue = (raw) => {
  if (raw[0] === '"' || raw[0] === "'") {
    const quoted = readQuotedValue(raw);
    return quoted ?? { value: '', trailing: '' };
  }
  const commentMatch = UNQUOTED_COMMENT.exec(raw);
  const valueText = commentMatch ? raw.slice(0, commentMatch.index + commentMatch[1].length) : raw;
  const value = valueText.trimEnd();
  return { value, trailing: raw.slice(value.length) };
};

const parseDefinitionLine = (line) => {
  const eol = line.endsWith('\r') ? '\r' : '';
  const match = ENV_DEFINITION.exec(line.slice(0, line.length - eol.length));
  if (!match) return null;
  const [, head, raw] = match;
  return { head, eol, ...parseEnvValue(raw) };
};

// The last definition wins, so it is also the one that gets updated.
const findLastDefinition = (lines) => {
  for (let index = lines.length - 1; index >= 0; index -= 1) {
    const definition = parseDefinitionLine(lines[index]);
    if (definition) return { index, ...definition };
  }
  return null;
};

const formatEnvValue = (value) => {
  if (UNQUOTED_SAFE.test(value)) return value;
  if (!value.includes("'")) return `'${value}'`;
  return `"${value.replace(/[\\"]/g, '\\$&')}"`;
};

const loadGlobalConfigForUpdate = (configPath) => {
  if (!fs.existsSync(configPath)) return {};
  let parsed;
  try {
    parsed = JSON.parse(fs.readFileSync(configPath, 'utf8'));
  } catch (error) {
    throw new Error(`Global config ${configPath} is not valid JSON; fix or remove it before storing a key.`);
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error(`Global config ${configPath} must contain a JSON object; fix it before storing a key.`);
  }
  return parsed;
};

export const hasLocalApiKey = (cwd = process.cwd()) => Boolean(getLocalApiKey(cwd));

export const getLocalApiKey = (cwd = process.cwd()) => {
  const envPath = resolveLocalEnvPath(cwd);
  if (!fs.existsSync(envPath)) return null;
  const definition = findLastDefinition(fs.readFileSync(envPath, 'utf8').split('\n'));
  return definition?.value.trim() || null;
};

// Only the last OPENAI_API_KEY line changes; every other byte of the file is kept.
export const setLocalApiKey = (key, cwd = process.cwd()) => {
  const value = normalizeKey(key);
  const envPath = resolveLocalEnvPath(cwd);
  const content = fs.existsSync(envPath) ? fs.readFileSync(envPath, 'utf8') : '';
  const lines = content.split('\n');
  const definition = findLastDefinition(lines);
  let updated;
  if (definition) {
    lines[definition.index] = `${definition.head}${formatEnvValue(value)}${definition.trailing}${definition.eol}`;
    updated = lines.join('\n');
  } else {
    const eol = content.includes('\r\n') ? '\r\n' : '\n';
    const separator = content && !content.endsWith('\n') ? eol : '';
    updated = `${content}${separator}${API_KEY_NAME}=${formatEnvValue(value)}${eol}`;
  }
  fs.writeFileSync(envPath, updated, { encoding: 'utf8', mode: 0o600 });
  return envPath;
};

export const hasGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) =>
  Boolean(getGlobalApiKey(homeDir));

export const getGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) => {
  const configPath = resolveGlobalConfigPath(homeDir);
  if (!fs.existsSync(configPath)) return null;
  try {
    const parsed = JSON.parse(fs.readFileSync(configPath, 'utf8'));
    return sanitizeValue(parsed?.[API_KEY_NAME]);
  } catch (error) {
    return null;
  }
};

// Other fields in the global config are kept. An unreadable file is an error, never overwritten.
export const setGlobalApiKey = (key, homeDir = process.env.HOME || process.env.USERPROFILE) => {
  const value = normalizeKey(key);
  const configPath = resolveGlobalConfigPath(homeDir);
  const config = loadGlobalConfigForUpdate(configPath);
  config[API_KEY_NAME] = value;
  ensureDir(resolveGlobalConfigDir(homeDir));
  const payload = JSON.stringify(config, null, 2);
  fs.writeFileSync(configPath, payload, { encoding: 'utf8', mode: 0o600 });
  return configPath;
};

